const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3200)}
function showErrorModal(message,title='Something went wrong'){
  const ar=state.lang==='ar';
  openModal(`<div class="error-dialog"><div class="error-dialog-icon">!</div><div class="eyebrow error-eyebrow">${ar?'تنبيه':'Error'}</div><h2>${esc(ar?({
    'Cannot submit yet':'لا يمكن تسليم الامتحان الآن','Unable to submit exam':'تعذر تسليم الامتحان','Exam attempt unavailable':'محاولة الامتحان غير متاحة','Desktop or laptop required':'يلزم استخدام كمبيوتر أو لابتوب','Assessment not open yet':'الامتحان غير متاح الآن','Assessment unavailable':'الامتحان لم يعد متاحًا','Unable to start exam':'تعذر بدء الامتحان'
  }[title]||title):title)}</h2><p class="error-dialog-message">${esc(message||'Unable to complete this action.')}</p><div class="actions error-dialog-actions"><button type="button" class="btn orange" onclick="closeModal()">${ar?'حسنًا':'Got it'}</button></div></div>`);
}
