function translateUI(){
  const ar=state.lang==='ar';
  document.documentElement.lang=ar?'ar':'en';
  document.documentElement.dir=ar?'rtl':'ltr';
  if(!ar)return;
  const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  for(const n of nodes){
    const raw=n.nodeValue, v=raw.trim();
    if(!v)continue;
    if(translations[v]) n.nodeValue=raw.replace(v,translations[v]);
  }
  app.querySelectorAll('input,textarea,select,[aria-label],[title]').forEach(el=>{
    ['placeholder','aria-label','title'].forEach(attr=>{
      const v=el.getAttribute(attr);
      if(v&&translations[v])el.setAttribute(attr,translations[v]);
    });
  });
}

async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.error||'Request failed');return d}
function fmtDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString():''}
function fmtSchedule(v){return v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Immediately'}
function localInputValue(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function scheduleState(e){const now=Date.now(),start=e.available_from?Date.parse(e.available_from):NaN,end=e.expires_at?Date.parse(e.expires_at):NaN;if(Number.isFinite(end)&&now>=end)return 'expired';if(Number.isFinite(start)&&now<start)return 'scheduled';return 'open'}
function layout(content,opts={}){const adminPortal=isAdminPortal(),parentPortal=isParentPortal();const ar=state.lang==='ar';if(parentPortal)return `<div class="shell parent-shell"><header class="topbar"><div class="brand"><div class="brand-name">منصة الامتحانات<small>${ar?'تعلّم · اختبر · تطوّر':'Learn · Test · Improve'}</small></div></div><div class="top-actions"><button class="circle-btn" onclick="toggleLang()">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn" onclick="toggleTheme()">${state.theme==='dark'?'☼':'✦'}</button></div></header>${content}<footer class="footer">منصة الامتحانات</footer></div>`;const auth=adminPortal?(state.me?.admin?`<button class="btn logout-btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:''):state.me?.user?`<button class="btn ghost dashboard-link" onclick="go('dashboard')">${ar?'لوحة الطالب':'Student Dashboard'}</button><button class="btn logout-btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:`<button class="btn orange" onclick="go('login')">${ar?'دخول الطالب':'Student Login'}</button>`;return `<div class="shell"><header class="topbar student-topbar"><a class="brand" href="#" onclick="go('home');return false" aria-label="Exam Platform"><div class="brand-name">منصة الامتحانات<small>${ar?'تعلّم · اختبر · تطوّر':'Learn · Test · Improve'}</small></div></a><nav class="student-nav"><button onclick="go('home')">${ar?'الرئيسية':'HOME'}</button><button onclick="document.getElementById('landing-features')?.scrollIntoView({behavior:'smooth'})">${ar?'عن المنصة':'ABOUT'}</button><button onclick="go('results')">${ar?'النتائج':'RESULTS'}</button><button onclick="go('skill-analysis')">${ar?'المهارات':'SKILLS'}</button></nav><div class="top-actions"><button class="circle-btn" onclick="toggleLang()" aria-label="Language">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn" onclick="toggleTheme()" aria-label="Theme">${state.theme==='dark'?'☼':'✦'}</button>${auth}</div></header>${content}<footer class="footer">${ar?'منصة الامتحانات · تعلّم، اختبر، تطوّر':'Exam Platform · Learn, Test, Improve'}</footer></div>`}
function render(){if(isParentPortal())return renderParent();const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.me?.user&&state.view==='home')state.view='dashboard';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if(state.view==='student-results'&&state.me?.user)return renderStudentResults();if(['skill-analysis','reading-practice','personal-progress','teacher-support'].includes(state.view)&&state.me?.user)return renderStudentFeature(state.view);if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
function parentToken(){const q=new URLSearchParams(location.search).get('parent');if(q)return q;return location.pathname.split('/')[2]||''}
async function renderParent(){const token=parentToken();app.innerHTML=layout(`<main class="page parent-page"><div id="parentContent" class="center"><div class="card empty">Loading student report…</div></div></main>`);try{const d=await api(`/api/parent/${encodeURIComponent(token)}`),results=d.results||[],avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0,best=results.length?Math.max(...results.map(r=>Number(r.percentage||0))):0,passed=results.filter(r=>r.passed).length,weak=(d.skills||[]).slice(0,3);document.getElementById('parentContent').innerHTML=`<section class="parent-report"><div class="parent-header card"><div><div class="eyebrow">Parent Follow-up</div><h1>${esc(d.student.full_name)}</h1><p class="muted">${esc(d.student.student_id)} · ${esc(d.student.grade_level||'')} · ${d.student.education_system==='azhar'?'Azhar':'General'}</p></div><div class="parent-badge">Live performance report</div></div><div class="student-stats"><div class="card student-stat"><span>Exams completed</span><b>${results.length}</b><small>${passed} passed</small></div><div class="card student-stat"><span>Average score</span><b>${avg.toFixed(1)}%</b><small>Across all completed exams</small></div><div class="card student-stat"><span>Best score</span><b>${best.toFixed(1)}%</b><small>Highest result</small></div><div class="card student-stat"><span>Pass rate</span><b>${results.length?(passed/results.length*100).toFixed(0):0}%</b><small>Successful exams</small></div></div><section class="card parent-section"><div class="eyebrow">Exam history</div><h2>Results</h2><div class="parent-results">${results.length?results.map(r=>`<div class="parent-result"><div><b>${esc(r.title)}</b><small>${fmtDate(r.created_at)}</small></div><div><strong>${Number(r.percentage).toFixed(1)}%</strong><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></div></div>`).join(''):'<div class="empty">No completed exams yet.</div>'}</div></section><section class="card parent-section"><div class="eyebrow">Skill profile</div><h2>Areas to support</h2>${weak.length?`<div class="skill-report-grid">${weak.map(x=>`<div class="skill-report"><div><b>${esc(x.skill)}</b><small>${x.questions} questions</small></div><strong>${Number(x.percentage||0).toFixed(0)}%</strong><div class="skill-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.percentage)||0))}%"></span></div></div>`).join('')}</div>`:'<p class="muted">Skill analysis will appear after skill-tagged questions are completed.</p>'}</section><section class="card parent-section parent-chat-section"><div class="parent-chat-head"><div><div class="eyebrow">Teacher communication</div><h2>Messages with the teacher</h2><p class="muted">Send questions or follow-up notes directly from this private parent link.</p></div><span class="chat-badge">Private</span></div><div id="parentChat" class="parent-chat"><div class="empty">Loading messages…</div></div></section></section>`;await loadParentChat(token)}catch(x){document.getElementById('parentContent').innerHTML=`<div class="card error-box"><div class="error-icon">!</div><h2>Unable to open this report</h2><p class="muted">${esc(x.message||'The parent link is invalid or unavailable.')}</p></div>`}}
async function loadParentChat(token=parentToken()){const el=document.getElementById('parentChat');if(!el)return;try{const d=await api(`/api/parent/${encodeURIComponent(token)}/messages`);renderParentChat(d.messages||[],token)}catch(x){el.innerHTML=`<div class="error-box"><b>Unable to load messages.</b><p class="muted">${esc(x.message)}</p></div>`}}
function renderParentChat(messages,token=parentToken()){const el=document.getElementById('parentChat');if(!el)return;el.innerHTML=`<div class="chat-thread">${messages.length?messages.map(m=>`<div class="chat-message ${m.sender_type==='parent'?'from-parent':'from-teacher'}"><div class="chat-message-meta"><b>${m.sender_type==='parent'?'You':'Teacher'}</b><span>${fmtDate(m.created_at)}</span></div><div class="chat-bubble">${esc(m.message).replace(/\n/g,'<br>')}</div></div>`).join(''):'<div class="chat-empty">No messages yet. Start the conversation with your teacher.</div>'}</div><form class="parent-chat-compose" onsubmit="sendParentMessage(event,'${esc(token)}')"><textarea name="message" maxlength="2000" rows="3" required placeholder="Write a message to the teacher…"></textarea><button class="btn orange">Send message</button></form>`;const thread=el.querySelector('.chat-thread');if(thread)thread.scrollTop=thread.scrollHeight}
async function sendParentMessage(e,token=parentToken()){e.preventDefault();const f=new FormData(e.target),message=String(f.get('message')||'').trim();if(!message)return;const btn=e.target.querySelector('button');if(btn)btn.disabled=true;try{await api(`/api/parent/${encodeURIComponent(token)}/messages`,{method:'POST',body:JSON.stringify({message})});e.target.reset();await loadParentChat(token)}catch(x){showErrorModal(x.message)}finally{if(btn)btn.disabled=false}}

function renderHome(){app.innerHTML=layout(`<main class="student-landing"><section class="landing-frame"><div class="landing-hero"><div class="landing-copy"><div class="landing-mini">EXAM PLATFORM · ASSESSMENT · PROGRESS</div><div class="landing-greeting">Hello</div><h1>Learn <span>better.</span><br>Progress <span>clearly.</span></h1><p>A focused learning and assessment experience for students. Take your assigned exams, understand your performance, and know exactly what to practice next.</p><div class="landing-actions"><button class="landing-primary" onclick="go('login')">Student Login <span>↗</span></button><div class="landing-note"><b>Your teacher manages your account.</b><span>No public registration required.</span></div></div></div><div class="landing-visual"><div class="landing-orb landing-orb-one"></div><div class="landing-orb landing-orb-two"></div><div class="landing-image-frame"><img src="/teacher.png" alt="English Teacher"><div class="landing-teacher-card"><small>YOUR TEACHER</small><strong>Mr. Zahran Abdel Aty</strong><span>Preparatory & Secondary · General & Azhar</span></div></div></div></div><div class="landing-scroll"><span>01</span><i></i><span>Explore the platform</span></div></section><section id="landing-features" class="landing-features"><div><div class="eyebrow">Built for better outcomes</div><h2>More than an online exam.</h2></div><div class="landing-feature-grid"><div><b>Skill-based assessment</b><span>Vocabulary, Grammar, Reading, Writing, Listening and more.</span></div><div><b>Detailed results</b><span>Understand the result instead of seeing one score only.</span></div><div><b>Progress over time</b><span>Track improvement from one assessment to the next.</span></div></div></section></main>`)}

function renderAdminLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Administration</div><h1>Control center.</h1><p class="muted">Authorized administrators only.</p><form class="form" onsubmit="adminLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Admin Login</button></form><p class="small-text muted">Student? <span class="link" onclick="go('login')">Student login</span></p></div></div></main>`)}
async function adminLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');state.view='admin';render()}catch(x){showErrorModal(x.message)}}
