async function studentResultDetail(id){try{const d=await api(`/api/results/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Exam review</div><h2>${esc(d.result.title)}</h2><p class="muted">${Number(d.result.percentage).toFixed(1)}% · ${d.result.passed?'Passed':'Not passed'}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="stack">${d.answers.map((a,i)=>{const opts={A:a.option_a,B:a.option_b,C:a.option_c,D:a.option_d};const selected=a.selected_answer?`${a.selected_answer}. ${opts[a.selected_answer]||''}`:'No answer';const correct=`${a.correct_answer}. ${opts[a.correct_answer]||''}`;return `<div class="answer-review-card card ${a.is_correct?'answer-correct':'answer-wrong'}"><div class="answer-review-head"><b>Question ${i+1}</b><span class="answer-state">${a.is_correct?'✓ Correct':'✕ Incorrect'}</span></div><strong>${esc(a.question_text)}</strong><div class="answer-box ${a.is_correct?'green':'red'}"><b>Your answer</b><span>${esc(selected)}</span></div>${!a.is_correct?`<div class="answer-box green"><b>Correct answer</b><span>${esc(correct)}</span></div>`:''}</div>`}).join('')}</div>`)}catch(x){showErrorModal(x.message)}}
async function renderDashboard(){let exams=[],results=[];try{[exams,results]=await Promise.all([api('/api/exams'),api('/api/results')])}catch(x){showErrorModal(x.message)}const passed=results.filter(r=>r.passed).length;const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;const best=results.length?Math.max(...results.map(r=>Number(r.percentage||0))):0;app.innerHTML=layout(`<main class="student-home page"><section class="student-welcome"><div class="welcome-copy"><div class="eyebrow">Student dashboard</div><h1>Hi, ${esc(state.me.user.fullName)} 👋</h1><p>Your learning journey is measurable. Take your assigned exams, understand your strengths, and know exactly what to practice next.</p><div class="student-meta"><span>${esc(state.me.user.grade||'Student')}</span><span>${state.me.user.educationSystem==='azhar'?'Azhar':'General'}</span>${state.me.user.groupId?'<span>Group assigned</span>':''}</div></div><div class="teacher-hero"><img src="/teacher.png" alt="English Teacher"><div class="teacher-overlay"><small>YOUR TEACHER</small><b>Mr. Zahran Abdel Aty</b><span>English Teacher</span></div></div></section><section class="parent-value"><div><div class="eyebrow">Why this platform?</div><h2>Not just an exam — a clear learning path.</h2><p>Every answer becomes useful feedback, so the student and parent can see where improvement is needed instead of looking at a score alone.</p></div><div class="value-points"><div><b>🎯 Skill-based assessment</b><span>Vocabulary, Grammar, Reading, Writing, Listening & more.</span></div><div><b>📈 Real progress</b><span>Track improvement across exams, not just one result.</span></div><div><b>💡 Smart feedback</b><span>See strengths, weaknesses and what to practice next.</span></div></div></section><section class="feature-grid"><button type="button" class="feature-card" onclick="document.getElementById('student-exams')?.scrollIntoView({behavior:'smooth',block:'start'})"><span class="feature-icon blue">📝</span><div><b>Available Exams</b><small>Assigned assessments with clear timing and instructions.</small></div><span>›</span></button><button type="button" class="feature-card" onclick="go('results')"><span class="feature-icon purple">📊</span><div><b>My Results</b><small>Detailed scores and performance history.</small></div><span>›</span></button><button type="button" class="feature-card" onclick="go('skill-analysis')"><span class="feature-icon green">🎯</span><div><b>Skill Analysis</b><small>Know your strongest and weakest English skills.</small></div><span>›</span></button><button type="button" class="feature-card" onclick="go('personal-progress')"><span class="feature-icon cyan">🧭</span><div><b>Personal Progress</b><small>See whether your performance is improving over time.</small></div><span>›</span></button></section><section class="student-stats"><div class="card student-stat"><span>Exams completed</span><b>${results.length}</b><small>${passed} passed</small></div><div class="card student-stat"><span>Average score</span><b>${avg.toFixed(0)}%</b><small>Across completed exams</small></div><div class="card student-stat"><span>Best score</span><b>${best.toFixed(0)}%</b><small>Your current peak</small></div><div class="card student-stat"><span>Next step</span><b>${exams.length?'Exam':'Practice'}</b><small>${exams.length?'You have an exam ready':'Keep building your skills'}</small></div></section><section class="section-head dashboard-section-head"><div><div class="eyebrow">Your assessments</div><h2>Ready when you are</h2></div></section><section id="student-exams" class="grid grid-3 student-exams">${exams.length?exams.map(examCard).join(''):`<div class="card empty">No active exams are available right now. Your teacher will add them here.</div>`}</section></main>`)}
